    function createPaperWarehousePanel(container, { mount, adapter, assets, onClose }) {
        let view = null, revision = 0, disposed = false;
        const release = () => { revision += 1; view?.destroy(); view = null; };
        return {
            async prepare() {
                if (disposed) return { applied: false };
                release(); const current = revision;
                view = mount(container, { adapter, ...assets, landscapeManaged: true, onClose });
                try {
                    const result = await view.ready;
                    return { applied: !disposed && current === revision && result?.loaded === true, loaded: result?.loaded ? 1 : 0, total: 1, error: result?.error };
                } catch (error) { return { applied: false, error: error?.message }; }
            },
            setActive(active, { preparing = false } = {}) { if (active) view?.resize(); else if (!preparing) release(); },
            resize() { view?.resize(); },
            setPaused(reason, value) { view?.setPaused(reason, value); },
            destroy() { disposed = true; release(); },
        };
    }













