                    const qL = item.label || (typeof QUALITY_LABELS !== 'undefined' && QUALITY_LABELS[item.quality]) || item.quality;
                    $('[data-item-title]').textContent = `Hộp Mù ${qL}`;
                    $('[data-description]').textContent = `Tiểu Trợ Thủ lén nhét một chiếc hộp mù vào túi đồ của bạn! Chiếc hộp mù đóng gói tỉ mỉ này có thể mở ra vật phẩm thần bí phẩm chất ${qL}.`;
                    $('[data-description-short]').textContent = `Chiếc hộp mù đóng gói tỉ mỉ này có thể mở ra vật phẩm thần bí phẩm chất ${qL}.`;
                    $('[data-price]').textContent = item.price;
