                    followupTokens: integer(input.followupTokens, d.followupTokens, 256, 16384, 'Giới hạn phản hồi hỏi thêm'),
                    contextDepth: integer(input.contextDepth, d.contextDepth, -1, 500, 'Số mẩu cốt truyện gần đây'),
