                    if (Array.isArray(context.recentTurns)) context = { ...context, recent: context.recentTurns.filter(turn => !turn.hidden && ['user', 'assistant'].includes(turn.role)).map(turn => `${turn.role === 'user' ? '<user>' : turn.name || 'Cốt truyện'}：${turn.text}`).join('\n\n') };
