                    const body = `<h2 id="modal-heading">Sổ Tay Bói Toán</h2><div class="history-controls"><label class="sr-only" for="history-search">Tìm theo câu hỏi</label><input id="history-search" placeholder="Tìm theo câu hỏi" value="${esc(historyFilter)}"><label class="check"><input id="favorite-filter" type="checkbox" ${onlyFavorites ? 'checked' : ''}>Chỉ xem yêu thích</label>${btn('export', 'Xuất sổ tay')}</div><div class="history-list">${records.length ? records.map(record => `<article class="history-item"><div class="history-cards" aria-hidden="true">${record.cards.map(card => art(card.revealed ? CARDS[card.id].image : 'back.webp', card.revealed && card.reversed ? 'upside-down' : '')).join('')}</div><div class="history-copy"><span class="small">${esc(date(record.createdAt))} · ${record.readings.length ? `${record.readings.length} lần giải bài` : `${record.cards.filter(card => card.revealed).length}/3 lá đã lật`}</span><h3>${esc(record.question)}</h3>${btn('open-record', 'Lật mở trang này', `data-record="${record.id}" ${disabled(vm.pending)}`)}${btn('favorite', record.favorite ? '★' : '☆', `data-record="${record.id}" aria-label="${record.favorite ? 'Bỏ yêu thích' : 'Yêu thích'}" ${disabled(busy())}`)}</div></article>`).join('') : '<div class="empty-state">Tại đây chưa có sổ tay phù hợp điều kiện.<br>Hãy trao một câu hỏi cho Christina, trang đầu tiên sẽ được lưu lại.</div>'}</div>`;
